function setupLine(element1, element2, baseColor) {
  brush.fill(baseColor, 1);
  brush.line(element1.x, element1.y, element2.x, element2.y); // Draws lines on top of the element1 and element2
  element1.color(baseColor); // Baseline color element1
  element2.color(baseColor); // Baseline color element2
  return true;
}

function sketch() { // New canvas redraw
  const base = [
    {type: 'rectangle', color: '#89d3e8', angle: 0, length: 200, width: 10}, // Hill
    {type: 'rectangle', color: '#55cc63', angle: 50, length: 40, width: 10}, // Top of hill
