    {type: 'line', color: '#d17a2c', length: 50, x: 0, y: 250, radius: 5} // Bullseye
  ];
  for (let i = 0; i < 100; i++) {
    let canvas = new ElementSlice();
    if (i === 0) base = [...base];
    else if (canvas.radius <= 88) base.splice(i, 1, canvas);
    canvas.redraw(base);
  }
}

