  //Sunset: Localize sun to bottom right.
  brush.noFill(); // Turns all fills transparent.
  brush.beginShape(0.8);
  brush.vertex(0, 200);   // Sun 0
  brush.vertex(100, 30);  // Top of hill
  brush.vertex(0, 100);   // Sun 1
  brush.endShape(true);

  //Sunrise: Localize hills on 3D hills.
  brush.noFill(); // Turns all fills transparent.
  brush.beginShape(1.5);
  brush.vertex(100, 30);  // Top of hill
  brush.vertex(0, 200);   // Sun 0
  brush.vertex(0, 100);   // Sun 1
  brush.vertex(100, 150); // Bottom of hill
  brush.endShape(true);

  //Sunrise: Localize hills on 3D hills.
  brush.noFill(); // Turns all fills transparent.
  brush.beginShape(1.5);
  brush.vertex(100, 30);  // Top of hill
  brush.vertex(0, 200);   // Sun 0
